import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))

    // Read first line: a, ta
    var st = StringTokenizer(br.readLine())
    val a = st.nextToken().toInt()
    val ta = st.nextToken().toInt()

    // Read second line: b, tb
    st = StringTokenizer(br.readLine())
    val b = st.nextToken().toInt()
    val tb = st.nextToken().toInt()

    // Read departure time hh:mm
    val timeStr = br.readLine().trim()
    val hh = timeStr.substring(0, 2).toInt()
    val mm = timeStr.substring(3, 5).toInt()
    val simStart = hh * 60 + mm
    val simEnd = simStart + ta

    val dayStart = 5 * 60          // 05:00 in minutes
    val dayEnd = 23 * 60 + 59      // 23:59 in minutes

    var count = 0
    var t = dayStart
    while (t <= dayEnd) {
        val busStart = t
        val busEnd = t + tb
        if (busEnd > simStart && busStart < simEnd) {
            count++
        }
        t += b
    }

    println(count)
}

