import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))

    // Read first line: a, ta
    var st = StringTokenizer(reader.readLine())
    val a = st.nextToken().toInt()
    val ta = st.nextToken().toInt()

    // Read second line: b, tb
    st = StringTokenizer(reader.readLine())
    val b = st.nextToken().toInt()
    val tb = st.nextToken().toInt()

    // Read departure time hh:mm
    val timeStr = reader.readLine().trim()
    val parts = timeStr.split(":")
    val h = parts[0].toInt()
    val m = parts[1].toInt()

    val startSimion = h * 60 + m
    val endSimion = startSimion + ta

    val dayStart = 5 * 60
    val dayEnd = 24 * 60 - 1  // 23:59

    var count = 0
    var t = dayStart
    while (t <= dayEnd) {
        val arrival = t + tb
        // Check if intervals (t, arrival) and (startSimion, endSimion) intersect
        if (t < endSimion && startSimion < arrival) {
            count++
        }
        t += b
    }

    println(count)
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))

    // Read first line: a, ta
    var st = StringTokenizer(reader.readLine())
    val a = st.nextToken().toInt()
    val ta = st.nextToken().toInt()

    // Read second line: b, tb
    st = StringTokenizer(reader.readLine())
    val b = st.nextToken().toInt()
    val tb = st.nextToken().toInt()

    // Read departure time of Simion
    val timeStr = reader.readLine().trim()
    val parts = timeStr.split(":")
    val sh = parts[0].toInt()
    val sm = parts[1].toInt()
    val simStart = sh * 60 + sm
    val simEnd = simStart + ta

    // Time range for buses: from 05:00 (300) to 23:59 (1439)
    val dayStart = 5 * 60
    val dayEnd = 23 * 60 + 59

    var count = 0

    // Iterate over all buses from B to A
    var departB = dayStart
    while (departB <= dayEnd) {
        val arriveA = departB + tb

        // Check if intervals [departB, arriveA] and [simStart, simEnd] intersect
        if (departB <= simEnd && simStart <= arriveA) {
            // Exclude encounters exactly at start or end cities
            if (!(arriveA == simStart || departB == simEnd)) {
                count++
            }
        }

        departB += b
    }

    println(count)
}

